import{_ as t,a,o as n,ai as o}from"./chunks/framework.BbOtTPsL.js";const u=JSON.parse('{"title":"Invoices","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/sales/invoices/index.md","filePath":"api/graphql-api/admin/sales/invoices/index.md","lastUpdated":1781099665000}'),i={name:"api/graphql-api/admin/sales/invoices/index.md"};function d(r,e,s,c,h,l){return n(),a("div",null,e[0]||(e[0]=[o('<h1 id="invoices" tabindex="-1">Invoices <a class="header-anchor" href="#invoices" aria-label="Permalink to &quot;Invoices&quot;">​</a></h1><p>The Invoices menu is the store-wide list of every invoice that has been generated across all orders, plus the actions you can take on a single invoice. It mirrors the admin <strong>Sales → Invoices</strong> screen.</p><h2 id="when-a-row-appears-here" tabindex="-1">When a row appears here <a class="header-anchor" href="#when-a-row-appears-here" aria-label="Permalink to &quot;When a row appears here&quot;">​</a></h2><p>An invoice row exists only after an invoice has been <strong>generated</strong> for an order — created manually (the Create Invoice mutation) or auto-generated if your store enables auto-invoicing. Placing or paying for an order does not by itself create an invoice; until one is generated, the order has no row in this menu.</p><h2 id="state-—-what-each-value-means" tabindex="-1"><code>state</code> — what each value means <a class="header-anchor" href="#state-—-what-each-value-means" aria-label="Permalink to &quot;`state` — what each value means&quot;">​</a></h2><p>In practice the grid shows just two badges — <strong>Paid</strong> and <strong>Pending</strong>. The &quot;Overdue by N days&quot; you usually see is a <em>derived countdown</em> shown under a <strong>Pending</strong> invoice (see <a href="#payment-due-date-the-red-countdown">the countdown</a> below), <strong>not</strong> a stored state.</p><table tabindex="0"><thead><tr><th><code>state</code></th><th>Badge</th><th>Meaning</th></tr></thead><tbody><tr><td><code>paid</code></td><td>green <strong>Paid</strong></td><td>The invoiced amount has been <strong>captured</strong> — a payment transaction was recorded against it (cash-on-delivery, the &quot;record transaction&quot; option at create-invoice time, or a paid gateway).</td></tr><tr><td><code>pending</code></td><td>yellow <strong>Pending</strong></td><td>The invoice exists but the money has <strong>not been captured yet</strong>. This is the everyday non-paid state.</td></tr><tr><td><code>pending_payment</code></td><td>yellow <strong>Pending</strong></td><td>A programmatic variant of <code>pending</code> set by some payment flows; displayed identically.</td></tr><tr><td><code>overdue</code></td><td>red <strong>Overdue</strong></td><td>A status you can set <strong>manually</strong> via <a href="/api/graphql-api/admin/sales/invoices/mass-update-status.html">Mass Update Status</a>. Rarely used day-to-day — the &quot;Overdue by N days&quot; the grid normally shows is the derived countdown under a <strong>Pending</strong> invoice, whose stored <code>state</code> is still <code>pending</code>.</td></tr></tbody></table><p>There is <strong>no <code>refunded</code> invoice state</strong> — refunds are tracked separately under <a href="/api/graphql-api/admin/sales/refunds/">Refunds</a>, not on an invoice&#39;s <code>state</code>.</p><p><strong>Why an order can still read &quot;pending&quot; after you invoice it.</strong> Generating an invoice records <em>what is owed</em>, not that it has been <em>paid</em>. The invoice (and the order&#39;s payment state) flips to <code>paid</code> only when a payment transaction is recorded against it. So an invoiced order whose payment hasn&#39;t been captured — e.g. an offline method, or an invoice generated without recording a transaction — stays <code>pending</code> until the money is taken. Expected behaviour, not a defect.</p><h2 id="payment-due-date-the-red-countdown" tabindex="-1">Payment due date &amp; the red countdown <a class="header-anchor" href="#payment-due-date-the-red-countdown" aria-label="Permalink to &quot;Payment due date &amp; the red countdown&quot;">​</a></h2><p>For a <code>pending</code> invoice the admin grid shows a small red line under the status: a countdown to the <strong>payment due date</strong>. That due date is the invoice&#39;s creation date plus your store&#39;s configured <em>payment term</em> — the &quot;due duration&quot; in days, set under <strong>Sales → Invoice Settings → Payment Terms</strong>. While the due date is in the future the line reads &quot;N day(s) left&quot;; once it passes it turns red and reads &quot;<strong>Overdue by N day(s)</strong>&quot;. Either way the invoice&#39;s stored <code>state</code> is still <code>pending</code> — the countdown is a display only, never a separate state. The API returns the raw <code>state</code> and <code>createdAt</code>, so a client can reproduce the same line: <code>dueDate = createdAt + dueDuration(days)</code>, then compare to today.</p><h2 id="what-each-action-does" tabindex="-1">What each action does <a class="header-anchor" href="#what-each-action-does" aria-label="Permalink to &quot;What each action does&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Print Invoice (PDF)</strong></td><td>Downloads a print-ready PDF of the invoice — a binary <code>application/pdf</code> attachment. This is <strong>REST only</strong>; binary downloads aren&#39;t expressible over GraphQL.</td></tr><tr><td><strong>Send Duplicate Invoice</strong></td><td>Re-sends the invoice email to the customer. You can override the recipient with a custom email; otherwise it goes to the order&#39;s customer email. Re-delivers a copy without regenerating the invoice.</td></tr><tr><td><strong>Mass Update Status</strong></td><td>Bulk-sets the status flag (<code>pending</code> / <code>paid</code> / <code>overdue</code>) on the selected invoices. It is a <strong>manual flag only</strong> — it does <strong>not</strong> capture or reverse a payment, and it does not create a transaction. Use it to correct or annotate state, not to take money.</td></tr><tr><td><strong>Export (CSV)</strong></td><td>Downloads the invoices grid — with your current filters applied — as a CSV file. <strong>REST only</strong> (binary).</td></tr></tbody></table><p>Invoice <strong>creation</strong> is not in this menu — it runs against an order; see <a href="/api/graphql-api/admin/sales/orders/create-invoice.html">Create Invoice</a>.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/sales/invoices/list.html">List invoices</a></td><td><code>adminInvoices</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/sales/orders/get-invoice.html">Get a single invoice</a></td><td><code>adminInvoice(id:)</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/sales/orders/print-invoice.html">Print invoice (PDF)</a></td><td>REST only (binary)</td></tr><tr><td><a href="/api/graphql-api/admin/sales/orders/send-duplicate-invoice.html">Send duplicate invoice email</a></td><td><code>createAdminInvoiceSendDuplicate</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/sales/invoices/mass-update-status.html">Mass update status</a></td><td><code>createAdminInvoiceMassUpdateStatus</code> mutation</td></tr><tr><td><a href="/api/rest-api/admin/sales/invoices/export.html">Export invoices (CSV)</a></td><td>REST only — <code>GET /api/admin/invoices/export</code></td></tr></tbody></table><p>All Invoice operations require the <code>sales.invoices.view</code> permission and an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',17)]))}const g=t(i,[["render",d]]);export{u as __pageData,g as default};
